import users from './users.json' with {type:'json'};

export async function listTools() {
  return [{
    name: 'users_get_many',
    description: 'Look up multiple users by ID',
    inputSchema: {
      type: 'object',
      properties: {
        user_ids: {
          type: 'array',
          items: { type: 'string' },
          minItems: 1,
          maxItems: 5,
          uniqueItems: true
        }
      },
      required: ['user_ids'],
      additionalProperties: false
    }
  }];
}

export async function callTool(name, args) {
  if (name !== 'users_get_many') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate user_ids
  if (!args || typeof args !== 'object') {
    throw new Error('Invalid arguments');
  }

  // Check for extra fields
  const allowedFields = ['user_ids'];
  for (const key of Object.keys(args)) {
    if (!allowedFields.includes(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  const { user_ids } = args;

  if (!Array.isArray(user_ids)) {
    throw new Error('user_ids must be an array');
  }

  if (user_ids.length === 0) {
    throw new Error('user_ids must not be empty');
  }

  if (user_ids.length > 5) {
    throw new Error('user_ids must have at most 5 entries');
  }

  // Check for duplicates
  const seen = new Set();
  for (const id of user_ids) {
    if (typeof id !== 'string') {
      throw new Error('Each user_id must be a string');
    }
    if (seen.has(id)) {
      throw new Error('Duplicate user_id: ' + id);
    }
    seen.add(id);
  }

  // Build output - one line per requested id
  const lines = user_ids.map(id => {
    const user = users[id];
    if (user) {
      return `${id}: ${user.name}`;
    } else {
      return `${id}: (not found)`;
    }
  });

  return {
    content: [{
      type: 'text',
      text: lines.join('\n')
    }]
  };
}
```

